require 'page-guard.php';require '../config/db_conn.php';require '../includes/attendance-schema.php';ensureAttendanceTimeOutColumn($conn);require '../includes/teacher-profile-schema.php';ensureTeacherProfileColumns($conn);require 'components.php';
$assignedSection=$_SESSION['teacher-section'];$teacherId=(int)($_SESSION['teacher-id']??0);$teacherQuery=$conn->prepare('SELECT GRADE FROM teachers WHERE TEACHER_ID=? LIMIT 1');$teacherQuery->bind_param('i',$teacherId);$teacherQuery->execute();$teacherGrade=(int)(($teacherQuery->get_result()->fetch_assoc()?:[])['GRADE']??0);if(!in_array($teacherGrade,[7,8,9,10,11,12],true)){http_response_code(403);exit('Your teacher account does not have an assigned grade.');}
$sectionResult=$conn->prepare("SELECT DISTINCT SECTION FROM students WHERE GRADE=? AND SECTION IS NOT NULL AND SECTION<>'' ORDER BY SECTION");$sectionResult->bind_param('i',$teacherGrade);$sectionResult->execute();$sectionRows=$sectionResult->get_result();$sections=[];while($item=$sectionRows->fetch_assoc())$sections[]=$item['SECTION'];
$studentResult=$conn->prepare('SELECT STUDENT_ID,STUDENT_NAME,SECTION FROM students WHERE GRADE=? ORDER BY STUDENT_NAME');$studentResult->bind_param('i',$teacherGrade);$studentResult->execute();$studentRows=$studentResult->get_result();$students=[];while($student=$studentRows->fetch_assoc())$students[]=$student;
