<script>
const section=document.getElementById('section-filter'),student=document.getElementById('student-filter'),date=document.getElementById('date-filter'),rows=document.getElementById('attendance-rows'),exportLink=document.getElementById('export-link');
function update(){const params=new URLSearchParams({section:section.value,student:student.value,date:date.value});rows.innerHTML='<tr><td colspan="8" class="px-4 py-8 text-center text-slate-500">Loading records…</td></tr>';fetch('get-attendance.php?'+params).then(response=>response.text()).then(html=>rows.innerHTML=html).catch(()=>rows.innerHTML='<tr><td colspan="8" class="px-4 py-8 text-center text-rose-600">Could not load records.</td></tr>');exportLink.href='export-attendance.php?'+params;}
section.onchange=update;student.onchange=update;date.onchange=update;update();setInterval(update,10000);
